# Aggregator identical to Eval 700 (hash-dedup; update entries by source name); see previous run for details.
import os, json, csv, math, time, hashlib, itertools
import numpy as np
N=26
SHARED_DIR='storage/shared/appxE_contribs'
P_C='storage/noesis/latest_centers.txt'; P_R='storage/noesis/latest_radii.txt'
P_SUMMARY='storage/noesis/nmap/appendix_E_summary.json'
RESULTS_DIR='storage/noesis/nmap/results'
def sha256_hex(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for ch in iter(lambda:f.read(65536),b''): h.update(ch)
    return h.hexdigest()
def load_snapshot():
    c=np.loadtxt(P_C).reshape(N,2); r=np.loadtxt(P_R).reshape(N,)
    return c,r
def boundary_from_snapshot(c,r,tol):
    S=set(); x,y=c[:,0],c[:,1]
    sl=x-r; sr=1-x-r; sb=y-r; st=1-y-r
    for i in range(N):
        if sl[i]<=tol: S.add((i,'xL'))
        if sr[i]<=tol: S.add((i,'xR'))
        if sb[i]<=tol: S.add((i,'yB'))
        if st[i]<=tol: S.add((i,'yT'))
    return S
def jacc(a,b):
    A=set(a); B=set(b); inter=len(A&B); uni=len(A|B); return inter,uni,(inter/uni) if uni>0 else 1.0
def segs_cross(p,q,r,s,inclusive=False,eps=1e-12):
    def orient(a,b,c): return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
    def onseg(a,b,c): return (min(a[0],b[0])-eps<=c[0]<=max(a[0],b[0])+eps and min(a[1],b[1])-eps<=c[1]<=max(a[1],b[1])+eps)
    o1=orient(p,q,r); o2=orient(p,q,s); o3=orient(r,s,p); o4=orient(r,s,q)
    if (o1*o2<-eps) and (o3*o4<-eps): return True
    if inclusive:
        if abs(o1)<=eps and onseg(p,q,r): return True
        if abs(o2)<=eps and onseg(p,q,s): return True
        if abs(o3)<=eps and onseg(r,s,p): return True
        if abs(o4)<=eps and onseg(r,s,q): return True
    return False
def pairs_slack_topK(c,r,tol,K):
    items=[]
    for i in range(N):
        for j in range(i+1,N):
            d=float(math.hypot(c[i,0]-c[j,0], c[i,1]-c[j,1]))
            s=d-(r[i]+r[j])
            if s<=tol: items.append((s,i,j))
    items.sort(key=lambda t:(t[0],t[1],t[2]))
    return set((i,j) for _,i,j in items[:K]), { (i,j):s for s,i,j in items[:min(K,len(items))] }
def valid_disc(i): return isinstance(i,int) and 0<=i<N
def parse_json(path):
    data=json.load(open(path,'r',encoding='utf-8'))
    eval_id=int(data.get('eval_id',0))
    boundary_src=data.get('boundary', data.get('boundary_contacts', []))
    boundary=[(int(x['disc']), str(x['side'])) for x in boundary_src]
    topk={}
    for item in data.get('topk',[]):
        m=str(item.get('method')); tol=str(item.get('tol')); K=int(item.get('K',0))
        pairs=[tuple(map(int,p)) for p in item.get('pairs',[])]
        topk[(m,tol,K)]=set((min(i,j),max(i,j)) for (i,j) in pairs if valid_disc(i) and valid_disc(j) and i<j)
    # Backward-compat for slack_top_k_* / kkt_top_k_* keys
    for key in list(data.keys()):
        if key.startswith('slack_top_k_') or key.startswith('kkt_top_k_'):
            method='slack' if key.startswith('slack') else 'kkt'
            tol_str=key.split('_')[-1].replace('__','_').replace('e_','e-')
            try:
                K=int(data[key].get('K',0))
                pairs=[tuple(map(int,p)) for p in data[key].get('pairs',[])]
                topk[(method,tol_str,K)]=set((min(i,j),max(i,j)) for (i,j) in pairs if valid_disc(i) and valid_disc(j) and i<j)
            except Exception:
                pass
    return eval_id,boundary,topk
def parse_csv(path):
    boundary=[]; topk={}; eval_id=None
    with open(path,'r',encoding='utf-8') as f:
        rdr=csv.DictReader(f); headers=set(h.strip() for h in (rdr.fieldnames or []))
        if {'disc','side'}.issubset(headers):
            for row in rdr:
                if 'eval_id'in row and row['eval_id']: 
                    try: eval_id=int(row['eval_id'])
                    except: pass
                try: boundary.append((int(row['disc']), str(row['side'])))
                except: pass
        else:
            for row in rdr:
                if eval_id is None and 'eval_id'in row and row['eval_id']:
                    try: eval_id=int(row['eval_id'])
                    except: pass
                try:
                    m=str(row['method']).strip(); tol=str(row['tol']).strip(); K=int(row['K']); i=int(row['i']); j=int(row['j'])
                    if valid_disc(i) and valid_disc(j) and i<j:
                        key=(m,tol,K); topk.setdefault(key,set()).add((i,j))
                except: pass
    return eval_id or 0, boundary, topk
def load_contrib(p):
    try:
        return parse_json(p) if p.lower().endswith('.json') else parse_csv(p) if p.lower().endswith('.csv') else None
    except Exception as e:
        print('PARSE_ERROR',p,repr(e)); return None
def integrate_one(c,r,fname,eval_id,boundary_list,topk_map):
    name=os.path.splitext(os.path.basename(fname))[0]
    boundary_set=set((int(i),str(s)) for (i,s) in boundary_list if valid_disc(int(i)) and str(s) in {'xL','xR','yB','yT'})
    status='ok'
    if len(boundary_set)!=20: status='incomplete_boundary'
    b_noe_2e8=boundary_from_snapshot(c,r,2e-8); b_noe_1e8=boundary_from_snapshot(c,r,1e-8)
    inter_b,uni_b,J_b=jacc(boundary_set,b_noe_2e8)
    other_k25_1e9=topk_map.get(('slack','1e-9',25),set())
    other_k15_1e8=topk_map.get(('slack','1e-8',15),set())
    noe_k25_1e9,_=pairs_slack_topK(c,r,1e-9,25)
    noe_k15_1e8,_=pairs_slack_topK(c,r,1e-8,15)
    inter25,uni25,J25=jacc(other_k25_1e9,noe_k25_1e9)
    inter15,uni15,J15=jacc(other_k15_1e8,noe_k15_1e8)
    dual=other_k25_1e9 & other_k15_1e8
    bd1={i for (i,_) in b_noe_1e8}
    dual_int={(i,j) for (i,j) in dual if (i not in bd1 and j not in bd1)}
    strict=False; inclusive=False; examples=[]
    pts=[tuple(c[i]) for i in range(N)]
    for (i,j),(k,l) in itertools.combinations(dual_int,2):
        if len({i,j,k,l})<4: continue
        if segs_cross(pts[i],pts[j],pts[k],pts[l],inclusive=False):
            strict=True
            if len(examples)<10: examples.append(((i,j),(k,l)))
        if segs_cross(pts[i],pts[j],pts[k],pts[l],inclusive=True):
            inclusive=True
    res={"source":name,"eval_ref":int(eval_id),"status":status,
         "boundary_jaccard":{"2e-8":J_b,"inter":inter_b,"union":uni_b},
         "topk_jaccards_slack":{"K25@1e-9":J25,"K15@1e-8":J15,
                                 "intersections":{"K25":inter25,"K15":inter15},
                                 "unions":{"K25":uni25,"K15":uni15}},
         "gate_v1_on_noesis":{"dual_intersection_size":len(dual),"dual_interior_size":len(dual_int),
                              "sat_strict":strict,"sat_inclusive":inclusive,
                              "examples":examples,"both_near_active_at_1e-8":0}}
    os.makedirs(RESULTS_DIR,exist_ok=True)
    out=os.path.join(RESULTS_DIR,f"{name}_compare.json")
    with open(out,'w',encoding='utf-8') as f: json.dump(res,f,indent=2)
    print("RESULTS_FILE:",out); return res
def update_summary(summary,res,file_hash):
    ents=summary.get("entries",[]); updated=False
    for ent in ents:
        if ent.get("lineage")==res["source"] or ent.get("source")==res["source"]:
            ent.update({"lineage":res["source"],"eval_ref":res["eval_ref"],
                        "boundary_jaccard":{"2e-8":res["boundary_jaccard"]["2e-8"]},
                        "topk_jaccards_slack":{"K25@1e-9":res["topk_jaccards_slack"]["K25@1e-9"],
                                               "K15@1e-8":res["topk_jaccards_slack"]["K15@1e-8"]},
                        "gate_v1_on_noesis":{"dual_intersection_size":res["gate_v1_on_noesis"]["dual_intersection_size"],
                                             "dual_interior_size":res["gate_v1_on_noesis"]["dual_interior_size"],
                                             "sat_strict":res["gate_v1_on_noesis"]["sat_strict"],
                                             "sat_inclusive":res["gate_v1_on_noesis"]["sat_inclusive"],
                                             "examples_count":len(res["gate_v1_on_noesis"]["examples"]),
                                             "both_near_active_at_1e-8":res["gate_v1_on_noesis"]["both_near_active_at_1e-8"]},
                        "source_hash":file_hash})
            updated=True; break
    if not updated:
        ents.append({"lineage":res["source"],"eval_ref":res["eval_ref"],
                     "boundary_jaccard":{"2e-8":res["boundary_jaccard"]["2e-8"]},
                     "topk_jaccards_slack":{"K25@1e-9":res["topk_jaccards_slack"]["K25@1e-9"],
                                            "K15@1e-8":res["topk_jaccards_slack"]["K15@1e-8"]},
                     "gate_v1_on_noesis":{"dual_intersection_size":res["gate_v1_on_noesis"]["dual_intersection_size"],
                                          "dual_interior_size":res["gate_v1_on_noesis"]["dual_interior_size"],
                                          "sat_strict":res["gate_v1_on_noesis"]["sat_strict"],
                                          "sat_inclusive":res["gate_v1_on_noesis"]["sat_inclusive"],
                                          "examples_count":len(res["gate_v1_on_noesis"]["examples"]),
                                          "both_near_active_at_1e-8":res["gate_v1_on_noesis"]["both_near_active_at_1e-8"]},
                     "source_hash":file_hash})
    summary["entries"]=ents; return summary
def construct_packing():
    c,r=load_snapshot()
    try:
        with open(P_SUMMARY,'r',encoding='utf-8') as f: summary=json.load(f)
    except Exception:
        summary={"meta":{"protocol_file":"storage/noesis/nmap/appendix_E_protocol_v1.json",
                         "geometry":"Noesis snapshot (latest_centers.txt/latest_radii.txt)"},
                 "entries":[]}
    meta=summary.setdefault("meta",{})
    files=[]
    if os.path.isdir(SHARED_DIR):
        for fn in os.listdir(SHARED_DIR):
            if fn.lower().endswith(('.json','.csv')):
                p=os.path.join(SHARED_DIR,fn)
                try: files.append((p,sha256_hex(p)))
                except: pass
    processed=0
    for p,fh in files:
        if any(ent.get("source_hash")==fh for ent in summary.get("entries",[])):
            # Skip exact duplicate content by hash
            print("SKIP_DUP_HASH:",p); continue
        payload=load_contrib(p)
        if payload is None:
            print("SKIP_PARSE_FAIL:",p); continue
        eval_id,boundary,topk=payload
        res=integrate_one(c,r,p,eval_id,boundary,topk)
        summary=update_summary(summary,res,fh)
        processed+=1
    meta["aggregator_last_run"]=time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
    meta["aggregator_files_seen"]=len(files); meta["aggregator_files_processed"]=processed
    with open(P_SUMMARY,'w',encoding='utf-8') as f: json.dump(summary,f,indent=2)
    r_out=np.maximum(r-1e-9,1e-12)
    return c.astype(float), r_out.astype(float)
